#include <iostream>
#include <vector>

class Graph {
private:
    int V; // Number of vertices
    std::vector<std::vector<int>> matrix;

public:
    // Constructor to initialize a V x V matrix with zeros
    Graph(int num_vertices) : V(num_vertices) {
        matrix.resize(V, std::vector<int>(V, 0));
    }

    // Adds an edge between vertex u and vertex v
    void addEdge(int u, int v, int weight = 1, bool directed = false) {
        matrix[u][v] = weight;
        if (!directed) {
            matrix[v][u] = weight; // Symmetric entry for undirected graphs
        }
    }

    // Prints the matrix structure to console
    void printMatrix() const {
        for (int i = 0; i < V; ++i) {
            for (int j = 0; j < V; ++j) {
                std::cout << matrix[i][j] << " ";
            }
            std::cout << "\n";
        }
    }
};

int main() {
    // Create an undirected graph with 4 vertices (0, 1, 2, 3)
    Graph g(4);

    g.addEdge(0, 1);
    g.addEdge(0, 2);
    g.addEdge(1, 2);
    g.addEdge(2, 3);

    g.printMatrix();

    return 0;
}

