function buildAdjacencyList(nodeCount, edges) {
  const adj = Array.from({ length: nodeCount }, () => []);
  for (const [u, v] of edges) {
    adj[u].push(v);
    adj[v].push(u);        // undirected: write it from both ends
  }
  return adj;
}

